/// <summary>
///  Sale invoice posting class extension
/// </summary>
[ExtensionOf(classStr(SalesInvoiceJournalPostBase))]
internal final class METSalesInvoiceJournalPostBase_Extension
{
}

Method.Source:
/// <summary>
/// This method get called when posting ends
/// </summary>
protected void endPost()
{
    SalesTable salesTable = custInvoiceJour.salesTable();

    next endpost();

    if ((salesTable.ReturnItemNum) || (salesTable.ReturnReasonCodeId && salesTable.METSalesOrderType == METVendParameters::find().SalesOrderType))
    {
        METClaimSOInvoicedBusinessEvent::newFromSalesTable(salesTable).send();
    }        

}

/// <summary>
/// Bug 209189: CB789 - Incorrect GL account for the additional journal posted for Excise price component
///     Creates a ledger dimension for the combination of ledger dimension default account and the account that is used for posting duty component COGS.
/// </summary>
/// <returns>
///     The ID of the <c>DimensionAttributeValueCombination</c> record.
/// </returns>
public LedgerDimensionDefaultAccount METGetLedgerDimensionAccountConsumption()
{
    LedgerDimensionDefaultAccount ledgerDimensionDefaultAccount;

    // Had to cast formletterProvider (CredManSalesFormletterProvider) to SalesFormletterProvider
    // Otherwise it is calling METLedgerDimensionLineAccountConsumption from METFormletterProvider_Extension (0) instead of METSalesFormletterProvider_Extension
    SalesFormletterProvider salesFormletterProvider = formletterProvider as SalesFormletterProvider;
    ledgerDimensionDefaultAccount = salesFormletterProvider.METLedgerDimensionLineAccountConsumption();

    return LedgerDimensionFacade::serviceCreateLedgerDimension(ledgerDimensionDefaultAccount, this.defaultDimension());
}
